SET plan_cache_mode=force_custom_plan; SET statement_timeout=120000; PREPARE hfs1579 AS SELECT COUNT(*) FROM resources WHERE tenant_id = $1 AND resource_type = $2 AND is_deleted = FALSE AND ((id IN (SELECT resource_id FROM search_index WHERE tenant_id = $1 AND resource_type = $2 AND param_name = 'patient' AND ((value_reference IS NOT NULL AND split_part(value_reference, '/', -1) = $3)))) AND (EXISTS (WITH scoped_composite AS MATERIALIZED (SELECT * FROM search_index WHERE tenant_id = $1 AND resource_type = $2 AND resource_id = resources.id AND param_name = 'code-value-quantity') SELECT 1 FROM scoped_composite WHERE param_name = 'code-value-quantity' AND composite_group IS NOT NULL AND (value_token_system IN ($4, 'urn:x-helios:implicit code system') AND value_token_code = $5) AND (value_quantity_value > $6))));
EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) EXECUTE hfs1579('default','Observation','01a0e8b8-323d-7341-9bfe-81346acf0c01','http://loinc.org','8302-2',160.0);
